(()=>{
  'use strict';

  const TRIGGERS=[
    {
      name:'The War That Tears the Veil',
      over:[
        'When hidden banners rise beneath a sky that remembers blood, six wounds shall open where the dead are counted but not mourned. At the final wound, the world behind the world shall no longer wait to be invited.',
        'The first kingdom will strike in secret, the second will answer in daylight, and the third blow will kill those standing in neighboring realities. When every truce becomes a weapon, the Veil will join the war.',
        'Beware the battle whose victors cannot agree which world they saved. Its refugees will carry new blood, its graves will speak, and its roads will remain open after the armies are gone.'
      ],
      stages:[
        {title:'The First Broken Truce',minor:{name:'The Guest’s Knife',poem:'The cup is overturned before either guest has drunk; the host dies carrying the guest’s knife, though no guest remembers drawing steel.',manifest:'A protected negotiation, diplomatic feast, prisoner exchange, or neutral conclave ends in a death or betrayal that can credibly be blamed on several factions.'},major:{name:'The House of Truce Under Siege',poem:'When sanctuary doors are barred from both sides, vengeance shall be recognized as law and the house of truce shall learn the grammar of siege.',manifest:'Neutral-ground protections are publicly or ritually abandoned by major powers, leaving safe houses, oath roads, parley halls, and mediators without recognized protection.'}},
        {title:'The Arming of Old Names',minor:{name:'The Empty Sheath',poem:'The sleeping blades are counted and one sheath is empty; an old name is spoken as an order by mouths too young to remember the first war.',manifest:'Ceremonial relics, ancestral weapons, old spell-keys, forbidden munitions, or oath-bound artifacts begin disappearing from collections that were never meant to be opened.'},major:{name:'The Ancient Blade Drawn',poem:'When the oldest weapon is used for a modern grievance, three worlds shall bleed from one wound and every treaty shall pretend it did not know the blade remained sharp.',manifest:'A faction deploys an ancient or hybrid weapon capable of harming bodies, souls, spirits, memories, infrastructure, or adjacent realities at the same time.'}},
        {title:'The Multiplication of Fronts',minor:{name:'Three Fires, One Wind',poem:'Three fires begin without shared tinder, yet every flame bends toward the same unseen wind and every witness swears they smelled the same ash.',manifest:'Unrelated local conflicts begin showing matching symbols, tactics, auxiliaries, coded phrases, logistics chains, or impossible coincidences.'},major:{name:'The Permanent War-Road',poem:'When distant battlefields answer one command, the road between them shall become permanent and the march shall teach the map a new vein.',manifest:'The war spreads across several regions, courts, spirit territories, or dimensions under linked command, shared patronage, or one hidden command structure.'}},
        {title:'The Dead Refuse the Boundary',minor:{name:'Voices Through Glass',poem:'The unburied speak through glass and wire, asking why the living have not finished their war; the radios answer in voices taken from graves.',manifest:'Battlefield dead, murdered envoys, sacrificed civilians, or erased combatants begin appearing in dreams, reflections, recordings, borrowed memories, or malfunctioning equipment.'},major:{name:'The Officers of the Dead',poem:'When the dead march under officers of their own, the grave shall cease to be a border and every casualty shall become a possible reinforcement.',manifest:'Mass death creates a stable crossing, revenant command structure, necromantic logistics route, or spirit corridor that remains open without active maintenance.'}},
        {title:'The Consensus of War',minor:{name:'The Impossible Artillery',poem:'Strangers name the same impossible artillery though none were taught its shape; the child, the soldier, and the censor draw one gun with three hands.',manifest:'Human witnesses in separate locations independently describe impossible weapons, creatures, magical effects, or combatants with matching operational detail.'},major:{name:'The Burial of Secrecy',poem:'When a billion eyes witness the hidden armies, disbelief shall be demobilized before dawn and secrecy shall be buried without honors.',manifest:'A public battle, mass recording, broadcast incident, leaked battlefield, or undeniable urban assault makes supernatural warfare globally visible.'}},
        {title:'The Veil Enlists',minor:{name:'The Wounded Change',poem:'The wounded change before they heal, and the battlefield begins choosing who may survive it; the medic’s hands remember medicine not yet invented.',manifest:'Magic strengthens in contested zones and metahuman traits, spirit marks, impossible healing, or battlefield mutations appear among refugees, medics, soldiers, or journalists.'},major:{name:'The Veil Beneath Every Flag',poem:'When both armies require the open wound to continue, the wound shall become the law of the world and the Veil shall enlist under every flag.',manifest:'The boundary remains permanently open because several belligerents depend upon crossings, spirit support, awakened logistics, or supernatural weapons to survive.'}}
      ]
    },
    {
      name:'The Human Counterstrike',
      over:[
        'When the blind forge a spear from stolen sight, they shall name every shadow enemy and every difference contagion. The first strike will be praised because its victims were hidden; the last will teach the world what was hiding.',
        'A ledger of monsters shall become a ledger of neighbors. Weapons without fear will carry the judgment of frightened men, and the hunted will answer with a sunrise no censor can conceal.',
        'Humanity will build the gate while believing it builds a wall. Every prison will become a school of resistance, every purge a revelation, and disbelief will die before the final launch order.'
      ],
      stages:[
        {title:'The Catalog of the Hidden',minor:{name:'The Seventh List',poem:'The clerk joins six harmless lists and discovers that the seventh contains families; the ink does not say monster until the child is counted.',manifest:'A mortal agency, corporation, hospital system, intelligence office, or research consortium merges unrelated anomaly records into a single threat index.'},major:{name:'The Ledger of Blood',poem:'When the hidden are numbered by blood instead of deed, the ledger shall become a weapon and every surname shall be asked to prove it is human.',manifest:'A transnational registry identifies whole bloodlines, communities, supernatural territories, suspected carriers, or inherited traits as targetable categories.'}},
        {title:'The Weapon Without Doubt',minor:{name:'The Applauded Silence',poem:'The first silence is called proof, though no one asks what screamed beyond the instruments; the weapon receives applause for making absence measurable.',manifest:'A prototype suppresses, kills, cages, blanks, or temporarily erases one minor entity, magical effect, spirit presence, or metahuman expression.'},major:{name:'The Weapon Without Conscience',poem:'When the weapon chooses faster than conscience can object, fear shall inherit command and no hand will admit it fired the spear.',manifest:'A scalable anti-supernatural weapon, autonomous targeting network, sterilization protocol, or reality-denial system is approved for deployment.'}},
        {title:'The Legal Cleansing',minor:{name:'The Temporary Ink',poem:'The exception is written in temporary ink, yet every jailer receives a permanent key and every judge learns not to ask where the doors have gone.',manifest:'Emergency powers remove due process from anomaly investigations, secret detention, medical quarantine, asset seizure, or protective custody.'},major:{name:'Birth Named Hostile',poem:'When law names birth itself a hostile act, the cleansing shall no longer require monsters; it will require only paperwork.',manifest:'Governments, corporate blocs, or security compacts authorize coordinated detention, sterilization, relocation, eradication, or inherited-status policy.'}},
        {title:'The First Successful Purge',minor:{name:'The Washed Windows',poem:'The empty neighborhood is praised because no witness remains to contradict the report; the windows are washed before anyone counts the shoes.',manifest:'A hidden enclave, safehouse, clinic, church, pack shelter, blood-court household, or spirit refuge disappears and is privately celebrated as clean.'},major:{name:'The First Silence Called Victory',poem:'When the first silence is called victory, every hidden nation shall prepare to answer in daylight and every survivor shall become a herald.',manifest:'A supernatural population center is destroyed, sterilized, exposed, or captured before it can warn allies, provoking organized retaliation.'}},
        {title:'The Answer in Daylight',minor:{name:'The Shared Maps',poem:'Ancient enemies exchange maps because the same executioner has learned both their names; knives are sheathed not from mercy, but arithmetic.',manifest:'Rival supernatural factions begin sharing intelligence, shelters, routes, medical resources, legal covers, or war plans against human hunters.'},major:{name:'The Hunted Beneath the Cameras',poem:'When the hunted stand together beneath the cameras, the secret world shall become a public army and every old feud shall wear one uniform.',manifest:'The hidden world forms a visible united defense, abandons secrecy, stages a public rescue, or deliberately reveals itself to stop the counterstrike.'}},
        {title:'The Wall Becomes the Gate',minor:{name:'Horns at the Barricade',poem:'Those guarding the wall awaken on both sides of it and no uniform can explain the change; the quarantine line grows horns in its sleep.',manifest:'Fear, exposure, weapons testing, stress, or contaminated environments produce spontaneous magical effects and transformations among civilians or soldiers.'},major:{name:'The Impossible Within Humanity',poem:'When humanity fires upon the impossible, the impossible shall answer from inside humanity and every barricade shall become a maternity ward.',manifest:'Counterstrike and retaliation make magic accepted fact while metahumanity awakens inside extermination infrastructure.'}}
      ]
    },
    {
      name:'The Rite of Returning Names',
      over:[
        'When the forgotten are named by mouths that never knew them, the lost age shall hear itself remembered and turn toward home. Six names will form the invitation; the seventh will be humanity, spoken without consent.',
        'The crown, root, chalice, road, grave, and star shall surrender the syllables they were sworn to hide. Those who call only their ancestors will awaken every inheritance.',
        'A ritual built for one people shall find the whole world listening. At the sixth returning, every dormant shape of humanity will answer, and no priest will possess enough names to send them back.'
      ],
      stages:[
        {title:'The Recovery of the First Name',minor:{name:'The Bleeding Syllable',poem:'A syllable without language is found in three records that were never allowed to meet; every reader bleeds from a different letter.',manifest:'A forbidden true-name fragment appears in unrelated archives, dreams, family records, relics, medical anomalies, or children’s drawings.'},major:{name:'The Ancestral Name',poem:'When the forgotten name changes flesh on command, the first ancestor shall know the road home and the road shall learn appetite.',manifest:'The initiating faction reconstructs a complete ancestral, divine, territorial, species, or patron name whose use causes repeatable physical or spiritual change.'}},
        {title:'The Gathering of Correspondences',minor:{name:'Six Keys Dream',poem:'The crown answers the root, the chalice answers the grave, and distance ceases to keep them apart; six keys dream of one lock.',manifest:'Relics, sacred sites, offices, bloodlines, dates, songs, contracts, or vanished territories from separate traditions begin resonating together.'},major:{name:'The Seventh Lock',poem:'When six separated keys turn beneath one hand, the world itself shall become the seventh lock and no altar shall remain merely local.',manifest:'Six required relics, sites, bloodlines, offices, patron spirits, or ritual jurisdictions fall under one ritual authority.'}},
        {title:'The Choir Without Knowledge',minor:{name:'The Harmless Phrase',poem:'Millions speak the harmless phrase and surrender a breath they do not remember giving; every advertisement becomes a hymn with its teeth removed.',manifest:'People repeat ritual phrases through entertainment, prayer, software, commerce, memes, medical forms, music, emergency alerts, or school lessons without knowing it.'},major:{name:'The Choir After Priests',poem:'When the choir can continue after every priest is dead, ignorance shall complete the invocation and consent shall be counted by echoes.',manifest:'A global population becomes an active ritual component without informed consent, allowing the rite to survive the loss of its original casters.'}},
        {title:'The Return of the Intended',minor:{name:'The Cradle’s Second Shadow',poem:'The first child bears the promised eyes and the faithful declare the old blood restored; nobody asks why the cradle casts two shadows.',manifest:'Chosen descendants manifest controlled traits, one lost spirit ecology briefly reappears, or a patron’s sign returns in a limited population.'},major:{name:'The Intended Dead in Sunlight',poem:'When the intended dead walk securely beneath the sun, the keepers shall remove the safeguards and call the breach inheritance.',manifest:'The targeted ancestors, patron, people, territory, lost season, or mythic ecology returns in stable form and acts without constant ritual support.'}},
        {title:'The Answer of Every Bloodline',minor:{name:'The Wrong Mouths',poem:'Children outside the covenant speak the returning names and wake in unfamiliar bodies; the priests insist the wrong mouths are lying.',manifest:'Unrelated families, communities, or populations display transformations explicitly excluded from the ritual design.'},major:{name:'Every Bloodline Answers',poem:'When every bloodline answers an invitation meant for one, transformation shall outrun classification and every genealogy shall become a door.',manifest:'Dormant metahuman patterns activate across multiple human populations, proving the rite cannot limit itself to chosen inheritors.'}},
        {title:'The Name That Cannot Be Withdrawn',minor:{name:'Letters in Ordinary Homes',poem:'Each erased letter reappears in another mouth, and each broken altar moves into an ordinary home; reversal becomes multiplication.',manifest:'Attempts to reverse, censor, disrupt, or silence the rite awaken additional spirits, forms, replacement sites, names, or hereditary expressions.'},major:{name:'Humanity as Lock and Key',poem:'When the species is spoken as one true name, no priest shall remain outside the ritual to end it and humanity shall become both lock and key.',manifest:'Humanity itself becomes the final name, making the return a permanent law of reality rather than a contained ritual result.'}}
      ]
    },
    {
      name:'The Consensus Recognition Cascade',
      over:[
        'When a billion witnesses agree upon the impossible, the impossible will no longer require permission. Six proofs shall pass from hand to hand; on the seventh morning every mirror will show the world people expect to see.',
        'The secret will not be revealed by wisdom but by repetition. A child, camera, corpse, crowd, and lie shall confirm the same forbidden fact until belief begins commanding reality.',
        'Beware the evidence that survives every explanation. Every denial will sharpen it, every erasure multiply it, and strangers shall reproduce the miracle at home.'
      ],
      stages:[
        {title:'The Unignorable Incident',minor:{name:'Angles No Camera Held',poem:'The image remains when every copy is destroyed, and strangers remember angles no camera held; the impossible acquires witnesses retroactively.',manifest:'A supernatural event is clearly recorded by unrelated witnesses, involves a public figure, survives deletion, or leaves evidence in systems that should not agree.'},major:{name:'The Name That Answers',poem:'When the impossible survives the laboratories of its enemies, the world shall give it a name and the name shall begin answering back.',manifest:'One incident survives professional forensic, scientific, religious, legal, or governmental review and becomes a global reference point.'}},
        {title:'The Failure of Explanations',minor:{name:'Too Many Shadows',poem:'Every denial answers a different question, yet all point toward the same forbidden truth; the cover story grows too many shadows.',manifest:'Official explanations contradict observable details, censorship creates more copies, or competing authorities cannot maintain one coherent denial.'},major:{name:'Censorship as Revelation',poem:'When censorship itself is accepted as evidence, concealment shall become revelation and every locked door shall publish its address.',manifest:'Scientific, religious, governmental, corporate, and media authorities publicly reject or abandon the same cover story.'}},
        {title:'The Reproducible Wonder',minor:{name:'The Kitchen-Table Miracle',poem:'The miracle leaves the temple and appears on kitchen tables beneath untrained hands; the forbidden becomes a household experiment.',manifest:'Ordinary people repeat a minor effect using leaked instructions, consumer devices, ritual fragments, belief exercises, songs, or tools.'},major:{name:'Wonder Without Permission',poem:'When strangers can repeat the wonder without permission, belief shall no longer require witnesses and secrecy shall lose its monopoly.',manifest:'A supernatural effect becomes reproducible by millions under ordinary conditions, making institutional denial practically impossible.'}},
        {title:'The Shared Vocabulary',minor:{name:'The Word Before Teachers',poem:'Children in distant cities invent the same word for what stands behind the glass; language arrives before the teachers.',manifest:'Unrelated cultures, social groups, emergency responders, schools, or online communities adopt common names for supernatural phenomena.'},major:{name:'The Ordinary Sentence',poem:'When the impossible is taught in schools and dispatched by emergency services, consensus shall begin reinforcing it with every ordinary sentence.',manifest:'A global practical language for magic, spirits, altered humanity, and supernatural incidents enters ordinary use.'}},
        {title:'The Expectation Effect',minor:{name:'The Haunted Map',poem:'The haunted road becomes haunted only after the map marks it so, yet the dead arrive on schedule; rumor discovers payroll.',manifest:'Legends, local fears, emergency labels, social panic, or public expectation begin shaping anomalies around places associated with them.'},major:{name:'Cities Under Different Laws',poem:'When expectation writes local law, neighboring cities shall inhabit different realities beneath one sky and every myth shall seek zoning.',manifest:'Communities generate stable magical rules, spirits, curses, protections, or transformations simply by expecting them strongly enough.'}},
        {title:'Belief Becomes Permission',minor:{name:'Disbelief as Minority Faith',poem:'The named thing no longer weakens when doubted, for enough mouths have taught it how to remain; disbelief becomes a minority religion.',manifest:'Spirits and metahuman traits appear first where public expectation, panic, worship, dread, or fascination is strongest.'},major:{name:'The Summoning Circle of Consensus',poem:'When observation sustains the hidden world, no censor shall possess enough darkness to close it again and consensus shall become a summoning circle.',manifest:'Collective recognition permanently rewrites the consensus boundary, allowing the supernatural to remain visible, repeatable, and legally unavoidable.'}}
      ]
    },
    {
      name:'The Mana Reservoir Rupture',
      over:[
        'The world has swallowed every delayed dawn and called the silence safety. Beneath six locks the unused morning grows teeth; when one keeper sells the key and another refuses the valve, the Sixth World shall arrive through every wound at once.',
        'Count not the years gained but the power denied release. Every sealed caern, dream, grave, gate, and blood-debt fills the same hidden sea until the smallest cracked vessel becomes an ocean.',
        'What was diverted was not destroyed, and what the factions hoarded was never owned. When six reservoirs answer beneath the skin of the world, every sleeping form shall rise with the pressure.'
      ],
      stages:[
        {title:'The Rising Measure',minor:{name:'The Quarreling Gauges',poem:'The gauges quarrel because none were built to number the weight beneath them; every needle points past its own confession.',manifest:'Instruments disagree as magical pressure exceeds their scales, vents recharge too quickly, or unrelated monitoring systems show the same impossible trend.'},major:{name:'The Buried Sea Learns Arithmetic',poem:'When every instrument fails in the same direction, denial shall become a measurement of its own and the buried sea shall learn arithmetic.',manifest:'Independent measurements confirm planetary accumulation beyond existing containment capacity.'}},
        {title:'The Market of Scarcity',minor:{name:'Cups Sold From a Rising Sea',poem:'The keepers sell cups from a rising sea and call the shortage proof of ownership; every drought invoice smells of salt.',manifest:'Factions trade access to vents, sacred sites, dream channels, release windows, ritual capacity, or safe discharge corridors while creating artificial shortages.'},major:{name:'The Contract-Dam',poem:'When relief is withheld for leverage, pressure shall learn the shape of the market and every contract shall become a dam.',manifest:'A cartel, sovereign, corporate bloc, spirit compact, or court controls several of the safest relief systems.'}},
        {title:'The Silencing of Valves',minor:{name:'The Forgotten Engineer',poem:'The first valve closes without command and the engineer’s name is removed from the schedule; the room remembers a worker nobody employed.',manifest:'One relief site fails suspiciously, technicians disappear, records rewrite, or incompatible controls appear after someone reports instability.'},major:{name:'Three Sewn Mouths',poem:'When three mouths of the buried sea are sewn shut, every weaker wound shall begin to speak and the quiet places shall become exits.',manifest:'Three major release systems are sabotaged, captured, deliberately closed, spiritually contaminated, or rendered politically unusable.'}},
        {title:'The Weaponization Attempt',minor:{name:'The Singing Crater',poem:'A cup of the hidden sea is poured upon an enemy and the victors demand a larger vessel; the test crater sings like a chapel.',manifest:'A faction tests a device, rite, engine, spell, military protocol, or corporate system that concentrates stored mana toward a target.'},major:{name:'Reservoirs Hear the Order',poem:'When pressure is taught to march as a weapon, every reservoir shall hear the order and every seal shall mistake itself for ammunition.',manifest:'Accumulated pressure is transferred into a weapon, ascension engine, monopoly technology, or linked reservoir command system.'}},
        {title:'The First Rupture',minor:{name:'The Antlered Rain',poem:'For one night the forest remembers beasts not born for this age, and some do not leave at dawn; the rain returns with antlers.',manifest:'A local breach causes temporary transformation, spirit weather, awakened wildlife, mythic ecology, altered births, or impossible terrain.'},major:{name:'The Inherited Fracture',poem:'When the first great vessel breaks, every connected seal shall inherit its fracture and every map shall learn where it is thin.',manifest:'A primary reservoir fails and cannot be resealed by its original mechanism.'}},
        {title:'The World Finds Every Wound',minor:{name:'The Unrecorded Wounds',poem:'Power rises through places no keeper recorded, choosing wounds older than every map; the grave, the storm drain, and the dream all open together.',manifest:'Unknown fault lines, graves, dreams, sacred places, ruins, municipal systems, hospitals, or forgotten rituals begin venting together.'},major:{name:'Pressure Made Flesh',poem:'When the hidden sea reaches every shore, transformation shall become the only remaining release valve and the Sixth shall arrive as pressure made flesh.',manifest:'The linked reservoir network ruptures globally and Awakening becomes the new equilibrium.'}}
      ]
    },
    {
      name:'The Sovereign Ascension',
      over:[
        'When one crown gathers every road, every name, and every hunger, the world will remember that no single hand was meant to close around it. Six rivals shall submit, and reality shall awaken a thousand heirs rather than accept one eternal sovereign.',
        'The victor will mistake silence for consent. Contracts will become borders, worship weather, memory taxation; at the sixth submission the throne shall touch the machinery of the world.',
        'Beware the power that wins without revealing the war. It shall own the gate, archive, city, dream, grave, and witness until Awakening becomes reality’s act of rebellion.'
      ],
      stages:[
        {title:'The Acquisition of Leverage',minor:{name:'The Unseen Creditor',poem:'Six owners discover that the same unseen creditor holds all their debts; the signatures differ, but the ink remembers one hand.',manifest:'One faction quietly acquires unrelated supernatural assets, contracts, relics, territories, favors, archives, debts, or legal claims.'},major:{name:'Leverage Becomes Sovereignty',poem:'When one hand can punish court, pack, spirit, state, and market alike, leverage shall become sovereignty and refusal shall become a ceremony.',manifest:'The faction controls a decisive asset in every major supernatural sphere.'}},
        {title:'The Reduction of Rivals',minor:{name:'The Protector’s Calendar',poem:'The proud kneel only for a season, yet the season’s calendar belongs to their protector; temporary shelter grows a throne room.',manifest:'Independent powers accept protection, debt, merger, emergency alliance, dependency, custody, or temporary vassalage.'},major:{name:'Independence by Permission',poem:'When rivals survive only by permission, independence shall become ceremonial and opposition shall require the sovereign’s stationery.',manifest:'Several sovereign factions accept vassalage and few credible counter-powers remain.'}},
        {title:'The Capture of Institutions',minor:{name:'The Second Signature',poem:'The mortal clerk stamps an ancient oath without seeing the second signature; the office printer learns a dead jurisdiction.',manifest:'Governments, corporations, courts, hospitals, platforms, militaries, or financial systems unknowingly enforce supernatural contracts and hidden authority.'},major:{name:'The Palace of Every Desk',poem:'When human law and hidden obligation issue the same command, the throne shall no longer require a palace and every desk shall become a gatehouse.',manifest:'State, corporate, and occult institutions fall under durable common control.'}},
        {title:'The Ownership of Memory',minor:{name:'The Marginal Names',poem:'The archive loses every rival name except in margins no reader remembers writing; history develops a preference.',manifest:'Records rewrite themselves, witnesses remember the ascending power as older than it is, or rival histories become harder to retrieve.'},major:{name:'History Taxes Dissent',poem:'When history can describe no world before the crown, rebellion shall appear to be madness and memory shall tax dissent.',manifest:'Collective history presents one sovereign order as inevitable, making opposition difficult to imagine, organize, or prove.'}},
        {title:'The Sixth Submission',minor:{name:'The Empty Final Chair',poem:'The final chair remains empty at the council because every road to it has been purchased; absence signs the treaty.',manifest:'The final independent rival is isolated, compromised, offered impossible terms, or prevented from appearing while coronation is prepared.'},major:{name:'The Monopoly Recognized by Reality',poem:'When the sixth rival submits, reality shall recognize a monopoly no treaty can balance and the throne shall touch the machinery of the world.',manifest:'The last necessary counter-power kneels, vanishes, submits, is absorbed, or is rendered metaphysically irrelevant.'}},
        {title:'Reality Creates Opposition',minor:{name:'Gifts of Conquered Houses',poem:'Children of conquered houses awaken bearing gifts their ancestors never possessed; the crown’s map births countries not yet drawn.',manifest:'Dormant bloodlines, spirits, gifts, alternate inheritances, impossible allies, or rival patrons awaken where the sovereign’s control is strongest.'},major:{name:'Rebellion Called Biology',poem:'When nothing remains outside the crown, the world shall manufacture outsiders from every sleeping bloodline and call the rebellion biology.',manifest:'Metahumanity and supernatural diversity erupt worldwide as automatic counterweights against monopoly.'}}
      ]
    }
  ];

  const SOURCES={
    Fae:{
      label:'Fae oath vision',
      artifacts:['The fever vision of the Moth-Crowned Envoy','The parley-song of the White Animal','The Orchard Court dream of the Uninvited Child','The oath spoken by the antlered guest at the Blue Supper','The rain-memory of a changeling returned in the wrong season','The mirror testimony of the bride who married tomorrow','The thorn-dream of the courtier without a shadow','The moonlit recitation of the guest beneath seven names'],
      acquisitions:['Remembered by a mortal who survived a fae banquet and could repeat it only while asleep.','Carried across the Veil by a changeling whose reflection continued speaking after the body fell silent.','Spoken through an oathbound spirit during a parley remembered in different seasons by every witness.','Recorded from a fevered envoy who spoke in several courtly voices at once.','Copied from the dream of a human guest after one night beneath an impossible moon.'],
      titles:['The Courtesy of {title}','The Misremembering of {title}','{title}, Dreamed by the Uninvited','The Oath Beneath {title}','The Fever Translation of {title}','{title} in the Season Without Doors','The Guest Called {title}','The Thorn-Mirror of {title}','The Seventh Meaning of {title}','{title}, or the Name the Court Refused','The Hospitality of {title}','When {title} Forgets Which Year It Is'],
      openings:['Before the guest arrived, the feast had already ended three times.','In the season translated as winter—though it may also mean accusation—the mirrors began speaking first.','The Court says this happened tomorrow; the witnesses insist it happened to their grandmothers.','There was a door, except the word for door is also the word for promise, wound, and younger sister.','The moon wore the host’s face and would not say whose invitation it had accepted.','A child made of rain recited the first line and forgot the language in which it was true.','At the blue supper every chair was occupied by an absence with excellent manners.','The orchard dreamed a trial, and all the fruit woke guilty.'],
      bridges:['Then the tense bent backward, and the warning answered a question no one had asked.','The witness became the accused, the accused became the road, and the road remembered being a knife.','Every proper name became a season, and every season denied having met the dead.','The sentence refused to decide whether it described a person, a kingdom, or an obligation inherited by both.','A second voice entered from the margin and denied that the first voice had ever been born.','The grammar became ceremonial, and consequence replaced causation with hospitality.','One word remained unspoken because every possible meaning would have created a debt.','The house bowed to the traveler, although neither the house nor the traveler had arrived.'],
      endings:['Whoever speaks the last line becomes responsible for whichever meaning arrives first.','The Court closes with a bow, which may be gratitude or the drawing of a weapon.','At dawn the ink becomes dew and the debt passes to the reader.','The final witness is an empty chair that remembers every guest by the wrong name.','The last word flowers into seven smaller promises, none willing to remain a metaphor.','The page ends where the invitation begins.','The moon withdraws its testimony and leaves the consequences under oath.','The future is thanked for attending, though it has not yet entered the room.'],
      gaps:['…','— and the white moth entered —','…the seventh courtesy…','…no guest, no host, only the invitation…'],
      rules:['Fae visions treat people, offices, seasons, and obligations as interchangeable masks; the literal noun may be wrong while the function is exact.','Hospitality language may conceal invasion, enthronement, plague, succession, or jurisdiction.','Contradictory futures can be simultaneous obligations rather than errors.','A statement in the future tense may be an accusation that the event has already occurred in oath-law.']
    },
    Blood:{
      label:'Blood-oracle vision',
      artifacts:['The Red Grail dream of the House Without Dawn','The ancestral memory of the Last Cupbearer','The vision of the Black Hart King’s unacknowledged heir','The scarlet succession dream beneath the Empty Round Table','The White Stag revelation of the exiled oracle','The blood-memory of the knight whose blade remembered him','The midnight vision of the Grail Widow','The lay sung by the mad minstrel of Nine Chalices'],
      acquisitions:['Inherited as a shared blood-memory by descendants belonging to rival houses.','Recited by a bloodline oracle during a succession rite that left every claimant dreaming the same king.','Recovered from the ancestral vision of an heir erased from every lawful genealogy.','Sung by a possessed minstrel whose verse changed according to the listener’s lineage.','Remembered through a relic wound that opened across several branches of one family.'],
      titles:['The Lay of {title}','The Red Chronicle of {title}','The Grail of {title}','{title} and the Uncrowned King','The Testament of {title}','The Ballad of {title}','The Scarlet Succession of {title}','The Knight Called {title}','The House That Inherited {title}','{title} Beneath the White Stag','The Last Cup of {title}','The Heraldry of {title}'],
      openings:['Hear now the lay beneath the red seal, and let no heir claim ignorance after the final verse.','In the reign of the king who wore no face, the cupbearer dreamed of a table set for the unborn.','When the White Stag crossed the field of banners, every knight knew which house would betray the realm.','The chronicler begins with lineage, for even calamity was required to name its father.','At the ninth coronation the grail filled itself and reflected a kingdom not yet conquered.','A black herald rode from the west carrying no message, only the genealogy of those who would die believing him.','The queen of the sealed chapel ordered this verse sung only to heirs already condemned.','In the hall of antlered shields, the youngest page heard old blood speaking through the empty throne.'],
      bridges:['Thereupon the herald changed his colors, and all who saw him swore the new device had always been his.','The chronicler names this treachery, though later houses call it inheritance.','At the third bell the court mistook obedience for loyalty and silence for consent.','The blood remembered what the living had agreed to forget.','No knight drew steel, yet every oath in the chamber suffered a mortal wound.','The cup passed from hand to hand until none could say whether it carried blessing, debt, or command.','Mercy entered the hall wearing the armor of necessity.','The old king laughed, for he recognized the war he had fathered without fighting.'],
      endings:['And so the cup passed to the one who had sworn never to drink.','The chronicle closes, but the bloodline continues the sentence.','No kingdom survived unchanged, though every house called the ending victory.','The White Stag departed carrying the crown upon its antlers and the true heir beneath its hooves.','Thus was the realm saved from one doom and lawfully delivered into another.','Whoever inherits the wound inherits the authority that made it.','The grail remained full after the court was empty.','So ends the lay; the succession remains disputed.'],
      gaps:['…','— the grail darkened —','…seven names beneath one crown…','…the bastard verse continues…'],
      rules:['Blood-oracle visions express catastrophe through legitimacy, inheritance, heraldry, and succession.','A king may be any authority able to make lineage claims enforceable.','Grail, crown, quest, and marriage can signify feeding systems, territorial control, or political annexation.','The heir may be a person, weapon, institution, city, or doctrine inheriting an unfinished obligation.']
    },
    Gaian:{
      label:'Spirit and shapechanger vision',
      artifacts:['The wound-song spoken through the dying wolf','The root-dream of the city spirit beneath the hospital','The shared moon-trance of the antlered pack','The river warning carried by six sleeping children','The mountain’s dream spoken through the mad hermit','The caern memory of bodies that remembered extinct forms','The migration prophecy of the birds above the poisoned watershed','The last vision of the marsh guardian'],
      acquisitions:['Received during a shared trance involving spirits, shapechangers, and animals across one wounded territory.','Spoken through a possessed ranger while the forest altered its migration paths.','Recovered from the ancestral visions of a shapechanger pack during involuntary transformation.','Translated from a river spirit’s testimony carried through dreams, animal behavior, and root growth.','Remembered by witnesses who slept within the same caern and woke bearing identical spirit marks.'],
      titles:['The Root-Song of {title}','When the Land Speaks {title}','The Antlered Memory of {title}','{title} Beneath Six Watersheds','The Wound Called {title}','The Migration of {title}','The Season That Carried {title}','{title} in the Mouth of the River','The Territory Dreaming {title}','The Bone-Circle of {title}','The Rain Mother’s {title}','The City-Spirit Remembers {title}'],
      openings:['The old elk stood in the poisoned river and would not drink until the city answered.','Under the hospital, roots found a room no architect had drawn and began singing through the pipes.','Six watersheds dreamed the same wound and woke facing one another.','The mountain spoke slowly because stone does not waste warning on urgency.','A she-wolf carried the first line three hundred miles without opening her mouth.','The city spirit called the event an infection; the forest called it a fence.','Rain fell upward from the graves and every bird changed its migration by one degree.','The glacier remembered a coastline no human map had survived to record.'],
      bridges:['The river answered with the names of every body hidden beneath its boundary.','What humans call coincidence, the territory calls circulation.','The wound moved from soil to blood to law without changing its smell.','Each species carried a different piece, and none possessed the whole until migration joined them.','The city mistook numbness for recovery.','The roots named the same event drought, trespass, and unborn weather.','A faceless spirit borrowed the traffic lights to continue speaking.','The land did not distinguish between a building, a government, and the hand that cut the first tree.'],
      endings:['The land does not promise revenge; it promises response.','By spring the wound has learned every name used to excuse it.','The animals leave first, and those who call their silence safety remain behind.','The river carries the final warning downstream where no jurisdiction can arrest it.','What the city buries, the watershed eventually introduces to the sea.','The mountain closes by moving one measurable inch.','The pack howls for a member not yet born.','At dawn the painted boundary is covered in tracks from the wrong side.'],
      gaps:['…','— hoofbeats beneath the earth —','…the river used the first-person plural…','…roots through the locked room…'],
      rules:['Spirit visions treat territory, body, institution, and ecosystem as organs of one living system.','Animal behavior may preserve chronology more reliably than spoken language.','Ownership is usually rendered as feeding, sheltering, circulation, trespass, or amputation.','The visible actor may be only the infection rather than the system benefiting from the wound.']
    },
    Dream:{
      label:'Collective dream prophecy',
      artifacts:['The Corridor Dream shared by eleven thousand sleepers','The Blue Room vision deleted from every patient file','The dream of the child recorded before the child was born','The Elevator Without Floors','The House Behind the Mirror','The impossible sunrise shared by a commercial sleep study','The Mouth-in-the-Wall nightmare','The collective false awakening of the missing city block'],
      acquisitions:['Compiled from matching visions of sleepers with no known contact.','Recorded during a contagious nightmare that crossed languages without changing its central images.','Recovered from a seer whose dreams continued through strangers after the seer awoke.','Spoken by patients during synchronized sleep paralysis in distant locations.','Remembered by witnesses who denied dreaming yet described the same impossible room.'],
      titles:['The Room Where {title}','You Dream {title} Before Waking','The Corridor Called {title}','{title} Behind the Mirror','The False Awakening of {title}','{title} in the House Without Morning','The Sleeper Who Remembers {title}','The Door That Dreams {title}','The Blue Room’s {title}','{title}, Repeated Until It Becomes True','The Mouth in the Wall Says {title}','The Elevator Descends to {title}'],
      openings:['You wake in the room after you have already left it.','There is a door behind your eyes and someone on the other side is dreaming you incorrectly.','Everyone in the dream knows your name except you.','The hallway is longer each time you remember it.','At 03:17 the sleepers turn toward the same wall and answer a question no one can hear.','You are holding an object that changes whenever you try to name it.','The city outside the window is yours, but all its streets lead to rooms from your childhood.','A child you have never met tells you this already happened in the next dream.'],
      bridges:['The scene changes without transition, but the wound remains in the same place.','When you look away, the witness becomes architecture.','Everyone repeats the same sentence with a different mouth.','The object is now behind you, though the dream insists you never turned around.','A second version of you enters carrying evidence from a future that denies your existence.','The room remembers an event your body has not experienced.','The cause is gone, but the reaction continues without it.','The clock loses a number and the missing hour begins occurring everywhere at once.'],
      endings:['You wake with dirt beneath your nails from a place that exists only in the dream.','The last door opens inward no matter which side you stand on.','Morning arrives, but one shadow remains asleep.','The dream ends when you understand that it has been rehearsing the world.','Everyone wakes remembering a different cause and the same consequence.','The mirror keeps watching after your reflection leaves.','You forget the warning and spend the day obeying it.','The dream does not end; it becomes ordinary enough to escape notice.'],
      gaps:['…','— you wake, but the room does not —','…someone is standing in the corner…','…the missing hour…'],
      rules:['Sequence is unreliable, but recurrence across unrelated sleepers is strong evidence.','A person in the vision may be a role worn by many actors.','Architecture can represent memory, policy, social expectation, or an actual place.','Some recurring symbols are self-fulfilling mechanisms rather than passive warnings.']
    },
    'Dead Reality':{
      label:'Dead-world lunatic prophecy',
      artifacts:['The starvation pages of the last occultist of Earth-Black-Salt','The wall-ravings of the blind survivor beneath the living sun','The black-rain sermon of the Hospital of Saint Nobody','The tunnel scripture of the ninth and twelfth last survivors','The ash-map of the lunatic cartographer','The final nightmare of the woman whose thoughts were being eaten','The confession spoken by an extinct city through one starving mouth','The last pages found beneath the sky that opened inward'],
      acquisitions:['Recovered from an occult survivor who crossed from a reality with no remaining living population.','Copied from a dead world where the final witnesses continued speaking after their recorded deaths.','Carried by a starving refugee whose visions contained streets and disasters absent from this reality.','Recorded from a lunatic who claimed the dead world itself was using his body as a mouth.','Recovered beside a seer whose final words continued in several unfamiliar voices.'],
      titles:['DO NOT CALL IT {title}','The Last Warning About {title}','{title} Killed Us Before We Named It','BLACK SALT: {title}','I Saw {title} Wearing Our Faces','The Wall Says {title}','{title}, Written After Everyone Died','The Ninth Survivor’s {title}','We Were Wrong About {title}','{title} Beneath the Dead Sun','The Hospital Gospel of {title}','No One Survived {title} Correctly'],
      openings:['I have not eaten since the sixth sunrise, although the sixth sunrise does not happen until tomorrow.','The walls began chewing before the people did, and now they know the taste of our names.','There were nine survivors when I counted. There are twelve now. Three of them are inside my thoughts.','Do not call this a metaphor. Metaphors did not eat the coast while we watched.','The dead lie less often than the emergency bells, but the bells have learned my mother’s voice.','I crossed out every name because the thing behind the sky follows the line of sight.','The hospital still announces visiting hours. I am the visitor. I am also every empty bed.','The sun is shining on the dead city and something is licking the light from the windows.'],
      bridges:['It happened next winter; I remember burying the ashes yesterday.','The thing has eaten the word for hunger, so I cannot tell you what remains inside me.','Every door opens into the same room now, and the room is thinking through my teeth.','I watched us stop it seven times. The eighth prevention was the first cause.','Someone has written my name on the casualty wall in handwriting I will learn tomorrow.','The city map has grown a district made from people who were never born.','I keep finding food in my pockets, but it screams when I swallow and returns as memory.','The voice beyond reality is eating from the edges inward; first dates, then faces, then the difference between warning and prayer.'],
      endings:['The last person alive was not the last thing speaking.','The sun is still shining. That is how I know there is no one left.','I can hear your world making the same choice we have not made yet.','The dead city has begun rehearsing your name.','The page continues after my hand stops.','Do not follow the road. We built it tomorrow from the bones we buried yesterday.','I am so hungry that the thing inside me has begun dreaming of your mouths.','When you read the final word, it will remember where you live.'],
      gaps:['…','— hungry hungry no mouth —','…tomorrow burned first…','…it is eating the sentence…','…twelve survivors, nine graves…'],
      rules:['Dead-world ravings may collapse cause, response, and aftermath into one event.','Apparent paranoia can preserve relationships erased from formal records.','First-person speech does not prove the speaker is still human.','The prophecy may describe events that failed to happen, happened in another reality, or became true because survivors tried to prevent them.']
    },
    Cult:{
      label:'Dead-god cult revelation',
      artifacts:['The brass-tablet revelation of the Keepers of the Ninth Well','The salt-desert vision of the Sleepless Vizier','The copper-leaf prophecy of the House of the Veiled Meridian','The recitation of the Mouth of the Drowned Star','The Forty Doors vision of the possessed pilgrim','The midnight revelation of the blind astronomer','The tomb-dream of the last lamp-keeper','The saffron-and-ash testament of the unwilling scribe'],
      acquisitions:['Taken from the visions of a possessed astrologer belonging to a forbidden sect of the buried gods.','Copied from a cult oracle who received the revelation during forty nights beneath a sealed desert tomb.','Recovered from the ravings of a pilgrim who returned from the salt wastes speaking for a dead star.','Transcribed from a tomb-seer whose visions were attributed to a god dead before human history.','Carried out of a hidden observatory by a mad scribe who believed the constellations were dictating scripture.'],
      titles:['The Parable of {title}','The Night of {title}','The Brass Tablet of {title}','{title} Beneath the Ninth Lamp','The Astrologer’s Warning Concerning {title}','The Secret Name of {title}','The Forty-Ninth Commentary on {title}','{title} in the House of the Buried Star','The Vizier’s Dream of {title}','The Testament of {title}','The Caravan of {title}','The Recitation of {title} Before the Sealed Well'],
      openings:['Attend, O keeper of the final lamp, and mistake not the silence of the dead for absence.','In the year when the red star cast no shadow, the astrologers found a second night hidden beneath the first.','The old scribe began with praise for no living king, but for the one whose throne lies beneath the sand.','At the caravanserai of the western waste, a traveler without a face purchased water with a vision and departed before arriving.','The vizier sealed the chamber with brass and salt, yet at dawn every lock bore the imprint of an inward-opening hand.','Beneath the ninth lamp the reciter spoke of a god slain before mankind learned death.','The astronomers lowered their instruments and listened, for the constellation had begun pronouncing their names.','A blind jurist declared that the dead god still possessed a throne because the world continued obeying its wound.'],
      bridges:['Thereafter consequence became the father of cause, and the child devoured both their names.','The same figure was servant, betrayer, vessel, and inheritance, and each title opened a different door.','The astrologer’s numbers became a hymn, and the hymn became a command written inside the tongue.','The tomb became a gate, the gate became a mouth, and the mouth remembered the first command spoken into darkness.','The king was a city, the city a body, the body a covenant, and the covenant a wound that remembered authority.','The verse denied the verse before it, and both were received beneath the same lamp.','Mercy and catastrophe differed only in the hand permitted to name them.','The lamps were counted again, and one more burned than the chamber had been built to hold.'],
      endings:['Thus the final lamp was extinguished, though its shadow continued burning upon the wall.','The wise departed before dawn; the faithful remained to hear the tomb breathe.','Whoever repeats the final verse becomes the road by which its answer travels.','The well was sealed with forty names, and every name awoke thirsty.','At sunrise the caravan possessed one traveler more and remembered one traveler less.','The astrologers broke their instruments, but the dead star continued measuring them.','No king inherited the warning; the warning inherited the kingdom.','The god remained dead, and therefore nothing living could command it to be silent.'],
      gaps:['…','— beneath the ninth lamp —','…forty doors; one key; no hand…','…the dead king dreamed of dawn…'],
      rules:['Kings, viziers, wells, lamps, stars, tombs, and caravans are offices within the parable rather than necessarily literal objects.','Death is treated as a change of jurisdiction rather than an ending.','Burial may signify containment, enthronement, dispersal, or the creation of a vessel.','Sequence is measured through conjunction, shadow, and repetition rather than calendar time.']
    }
  };

  const FACTIONS=['a high fae court','a blood-sovereign coalition','a Gaian spirit confederacy','a corrupted shapechanger alliance','a multinational hunter directorate','an elder cult network','a dream-market cartel','a mortal occult corporation','a state intelligence compact','a disputed Blacklight splinter operation'];
  const FACTION_METHODS={
    'a high fae court':['oath geometry','hospitality traps','seasonal jurisdiction','borrowed names','self-enforcing treaties'],
    'a blood-sovereign coalition':['lineage debt','feeding compacts','succession pressure','blood memory','inherited consent'],
    'a Gaian spirit confederacy':['territorial possession','ecological retaliation','spirit weather','pack memory','sacred-site pressure'],
    'a corrupted shapechanger alliance':['false pack-sign','contaminated guardianship','ritual predation','war-path inheritance','body-as-banner tactics'],
    'a multinational hunter directorate':['target registries','deniable raids','prototype weapons','quarantine language','extermination paperwork'],
    'an elder cult network':['pre-human grammar','apocalyptic patronage','sleeper recruitment','sacrificial logistics','buried-city theology'],
    'a dream-market cartel':['dream laundering','symbol trafficking','memory arbitrage','nightmare franchising','consensus bait'],
    'a mortal occult corporation':['contract capture','patent ritualism','asset extraction','private security theology','monopoly infrastructure'],
    'a state intelligence compact':['classified doctrine','black-budget containment','counter-anomaly bureaucracy','official denial loops','evidence compartmentalization'],
    'a disputed Blacklight splinter operation':['archive theft','counter-prophecy forgery','false custody trails','evidence poisoning','preventive catastrophe logic']
  };

  const $=id=>document.getElementById(id);
  const esc=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  function hash(text){let h=2166136261>>>0;for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
  function rng(seed){let x=hash(seed)||0x9e3779b9;return()=>{x^=x<<13;x^=x>>>17;x^=x<<5;return(x>>>0)/4294967296;};}
  function pick(random,list){return list[Math.floor(random()*list.length)];}
  function makeSeed(){return `BAP-${Date.now().toString(36).toUpperCase()}-${Math.floor(Math.random()*1679616).toString(36).padStart(4,'0').toUpperCase()}`;}
  function selectedValue(id){const value=$(id).value;return value==='random'?null:value;}
  function lowerFirst(text){return text?text.charAt(0).toLowerCase()+text.slice(1):text;}
  function fill(template,values){return template.replace(/\{(\w+)\}/g,(_,key)=>values[key]??'');}

  const PROHIBITED_PROPHECY=/\b(?:Charles|Blacklight|prediction model|prediction engine|forecast engine|suspected actor contamination|source-family reading|field-use reading|Charles flags|archive handling note|custody copy|operational conclusion)\b/i;

  function formatPassage(sourceKey,parts,random){
    const clean=parts.filter(Boolean).map(part=>part.trim()).filter(Boolean);
    const source=SOURCES[sourceKey];
    if(random()<0.24){const gap=pick(random,source.gaps);const position=1+Math.floor(random()*Math.max(1,clean.length-1));clean.splice(position,0,gap);}
    if(sourceKey==='Dream'||sourceKey==='Dead Reality')return clean.join(random()<0.55?'\n':'\n\n');
    const cut=Math.min(clean.length-1,2+Math.floor(random()*Math.max(1,clean.length-3)));
    return `${clean.slice(0,cut).join(' ')}\n\n${clean.slice(cut).join(' ')}`;
  }

  function sourceCore(sourceKey,event,stage,trigger,random){
    const core=event.poem;const eventName=event.name;const stageName=stage?.title||trigger.name;
    const frames={
      Fae:[`${core} The second meaning wears ${eventName} as a mask, but the first meaning has already gone hunting.`,`${core} In the other tense, ${eventName} is the guest and ${stageName} is the house that invited it.`,`${core} The moon calls this ${eventName}; the thorn calls it ${stageName}; neither will admit which name belongs to the wound.`,`${core} Whoever remembers ${eventName} correctly forgets why ${stageName} was ever considered possible.`],
      Blood:[`${core} Thus was ${eventName} entered into the red chronicle, though three houses denied the ink and four claimed the wound.`,`${core} The herald named it ${eventName}, and every banner in the hall displayed the device of ${stageName}.`,`${core} So the grail darkened before ${eventName}, and the youngest heir dreamed that ${stageName} had become a crown.`,`${core} The blade remembered ${eventName}, though no living knight confessed to drawing it.`],
      Gaian:[`${core} The roots named this ${eventName}, and the wounded territory carried the name through water, fur, stone, and sleeping flesh.`,`${core} The pack smelled ${eventName} before the first human witness saw it, and the river answered with ${stageName}.`,`${core} Beneath ${stageName}, the land grew a second pulse and every animal turned its head toward ${eventName}.`,`${core} The wound called itself ${eventName}; the city called it weather; the dead trees called it return.`],
      Dream:[`${core} You call it ${eventName}, but the room calls it by your childhood name.`,`${core} In the next awakening, ${eventName} is standing where ${stageName} used to be.`,`${core} Everyone remembers ${eventName} happening to someone else, and everyone wakes with the same bruise.`,`${core} The mirror shows ${eventName}; when you turn around, it has become ${stageName}.`],
      'Dead Reality': [`${core} They called it ${eventName} after it killed us, before it happened, while we were still laughing.`,`${core} ${eventName} happened next winter. I remember the ashes from yesterday. The thing inside my skull says ${stageName} was only the first mouth.`,`${core} I wrote ${eventName} on the wall, but it ate the letters and left me the taste of ${stageName}.`,`${core} We survived ${eventName} in the world that never existed. I am starving in its ruins now.`],
      Cult:[`${core} Thus did the keepers name it ${eventName}, and beneath the ninth lamp ${stageName} answered with a voice of brass.`,`${core} The vizier wrote ${eventName} upon salt, and the buried star replied by opening the gate of ${stageName}.`,`${core} In the Forty-Ninth Recitation, ${eventName} was the cup and ${stageName} the thirst that drank from it.`,`${core} The astrologer beheld ${eventName} beneath the dead constellation and bowed when ${stageName} cast a shadow without light.`]
    };
    return pick(random,frames[sourceKey]);
  }

  function composeProphecy(sourceKey,event,stage,trigger,seed){
    const random=rng(seed);const source=SOURCES[sourceKey];
    const parts=[pick(random,source.openings),sourceCore(sourceKey,event,stage,trigger,random),pick(random,source.bridges),pick(random,source.endings)];
    const text=formatPassage(sourceKey,parts,random);
    if(PROHIBITED_PROPHECY.test(text))throw new Error(`Prophecy purity violation for ${sourceKey}: ${text.match(PROHIBITED_PROPHECY)?.[0]}`);
    return text;
  }

  function eventTitle(sourceKey,event,seed){const random=rng(seed);const frame=pick(random,SOURCES[sourceKey].titles);return fill(frame,{title:event.name.replace(/^The\s+/i,'')});}
  function correspondence(event,seed){const random=rng(seed);const variants=[event.manifest,event.manifest.replace(/^A\s+/,'One possible event is a ').replace(/^The\s+/,'One possible event is that the '),`This may correspond to ${lowerFirst(event.manifest)}`];return pick(random,variants);}
  function interpretations(record,stage,event,kind,seed){const random=rng(seed);const source=SOURCES[record.source];const method=pick(random,FACTION_METHODS[record.faction]);return [`Literal reading: ${event.manifest}`,`Symbolic reading: the central image may describe a person, office, bloodline, territory, institution, ritual object, or public event performing the same role.`,`Source reading: ${pick(random,source.rules)}`,`Temporal reading: this ${kind.toLowerCase()} event may occur before, during, or after the other event filed under ${stage.title}; their shared stage does not make them causally dependent.`,`Counterintelligence reading: ${record.faction} could imitate the imagery through ${method}, exploit a genuine occurrence, or redirect blame toward a rival.`];}

  function buildRecord(triggerIndex,seed){
    const random=rng(`${seed}|record|${triggerIndex}`);const trigger=TRIGGERS[triggerIndex];const source=selectedValue('prophecy-source')||pick(random,Object.keys(SOURCES));const faction=selectedValue('prophecy-faction')||pick(random,FACTIONS);const posture=selectedValue('prophecy-clarity')||pick(random,['Veiled','Balanced','Direct']);
    const record={id:`BAP-${triggerIndex+1}-${hash(`${seed}|${triggerIndex}`).toString(16).toUpperCase().padStart(8,'0')}`,seed,triggerIndex,trigger,source,faction,posture};
    record.primarySource=pick(random,SOURCES[source].artifacts);record.acquisition=pick(random,SOURCES[source].acquisitions);
    const overarchingEvent={name:trigger.name,poem:pick(random,trigger.over),manifest:''};record.overarching=composeProphecy(source,overarchingEvent,null,trigger,`${seed}|${triggerIndex}|overarching`);
    record.stages=trigger.stages.map((stage,index)=>{
      const minor={title:eventTitle(source,stage.minor,`${seed}|${triggerIndex}|${index}|minor|title`),prophecy:composeProphecy(source,stage.minor,stage,trigger,`${seed}|${triggerIndex}|${index}|minor|prophecy`),correspondence:correspondence(stage.minor,`${seed}|${triggerIndex}|${index}|minor|correspondence`)};
      minor.interpretations=interpretations(record,stage,stage.minor,'Minor',`${seed}|${triggerIndex}|${index}|minor|interpretations`);
      const major={title:eventTitle(source,stage.major,`${seed}|${triggerIndex}|${index}|major|title`),prophecy:composeProphecy(source,stage.major,stage,trigger,`${seed}|${triggerIndex}|${index}|major|prophecy`),correspondence:correspondence(stage.major,`${seed}|${triggerIndex}|${index}|major|correspondence`)};
      major.interpretations=interpretations(record,stage,stage.major,'Major',`${seed}|${triggerIndex}|${index}|major|interpretations`);
      return {number:index+1,title:stage.title,minor,major};
    });
    return record;
  }

  function eventPanel(kind,event){return `<article class="event-fragment ${kind==='Minor'?'minor-fragment':'major-fragment'}"><div class="fragment-heading"><span>${kind.toUpperCase()} EVENT</span><strong>${esc(event.title)}</strong></div><span class="event-trigger-label">Event Trigger</span><blockquote>${esc(event.prophecy)}</blockquote><div class="event-correspondence"><span>Event Correspondence</span><p>${esc(event.correspondence)}</p></div><details class="interpretation-drawer"><summary>Open ${event.interpretations.length} interpretations</summary><ol>${event.interpretations.map(item=>`<li>${esc(item)}</li>`).join('')}</ol></details></article>`;}
  function renderRecord(record,open){return `<details class="prophecy-record" ${open?'open':''}><summary><span>${esc(record.id)}</span><strong>${esc(record.trigger.name)}</strong><em>Suspected actor: ${esc(record.faction)}</em></summary><article class="prophecy-card"><div class="intel-grid"><div class="intel-field"><span>Primary source</span><p>${esc(record.primarySource)}</p></div><div class="intel-field"><span>Acquisition</span><p>${esc(record.acquisition)}</p></div><div class="intel-field"><span>Suspected advancing faction</span><p>${esc(record.faction)}</p></div><div class="intel-field"><span>Interpretive posture</span><p>${esc(record.posture)}</p></div></div><div class="prophecy-major"><span>Major overarching prophecy</span><blockquote>${esc(record.overarching)}</blockquote></div><div class="stage-sequence">${record.stages.map(stage=>`<section class="stage-pair"><header><span>STAGE ${stage.number} OF 6</span><h3>${esc(stage.title)}</h3></header><div class="stage-pair-grid">${eventPanel('Minor',stage.minor)}${eventPanel('Major',stage.major)}</div></section>`).join('')}</div></article></details>`;}
  function textRecord(record){const lines=[`BLACKLIGHT RECOVERED PROPHECY ${record.id}`,`Awakening trigger: ${record.trigger.name}`,`Suspected advancing faction: ${record.faction}`,`Primary source: ${record.primarySource}`,`Acquisition: ${record.acquisition}`,'','MAJOR OVERARCHING PROPHECY',record.overarching];record.stages.forEach(stage=>{lines.push('',`STAGE ${stage.number} OF 6 — ${stage.title}`);for(const [kind,event] of [['MINOR',stage.minor],['MAJOR',stage.major]]){lines.push(`${kind} EVENT — ${event.title}`,'Event Trigger',event.prophecy,'Event Correspondence',event.correspondence,`${kind} INTERPRETATIONS`,...event.interpretations.map((item,index)=>`${index+1}. ${item}`));}});return lines.join('\n');}

  let currentText='';
  function generate(all){
    try{
      const seed=$('prophecy-seed').value.trim()||makeSeed();$('prophecy-seed').value=seed;const chosen=$('prophecy-trigger').value;const indices=all?TRIGGERS.map((_,index)=>index):[chosen==='random'?Math.floor(rng(`${seed}|trigger-select`)()*TRIGGERS.length):Number(chosen)];const records=indices.map(index=>buildRecord(index,seed));
      $('prophecy-output').innerHTML=records.map((record,index)=>renderRecord(record,index===0)).join('');currentText=records.map(textRecord).join('\n\n============================================================\n\n');$('prophecy-copy').disabled=false;$('prophecy-status').textContent=all?`Mounted all six trigger prophecies from key ${seed}.`:`Mounted ${records[0].id} from ${records[0].primarySource}.`;$('prophecy-output').scrollIntoView({behavior:'smooth',block:'start'});
    }catch(error){console.error(error);$('prophecy-status').textContent='The prophecy file could not be mounted because the generated text failed the prophecy-only validation.';}
  }

  $('prophecy-generate').addEventListener('click',()=>generate(false));
  $('prophecy-generate-six').addEventListener('click',()=>generate(true));
  $('prophecy-copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(currentText);$('prophecy-status').textContent='Prophecy file copied.';}catch(error){$('prophecy-status').textContent='Clipboard access was blocked. Select the mounted file manually.';}});
})();